changeSet.createProcedure:
CREATE OR REPLACE FUNCTION audit_row_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_old jsonb;
    v_new jsonb;
    v_record_id bigint;
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_new := to_jsonb(NEW);
        v_record_id := NEW.id;
    ELSIF TG_OP = 'UPDATE' THEN
        v_old := to_jsonb(OLD);
        v_new := to_jsonb(NEW);
        v_record_id := NEW.id;
    ELSE
        v_old := to_jsonb(OLD);
        v_record_id := OLD.id;
    END IF;

    EXECUTE format(
        'INSERT INTO %I.%I (record_id, operation, old_data, new_data, changed_at, db_user, app_user_id) '
        'VALUES ($1, $2, $3, $4, now(), current_user, $5)',
        TG_TABLE_SCHEMA, TG_TABLE_NAME || '_audit')
    USING v_record_id, TG_OP, v_old, v_new, current_setting('smartmentor.current_user_id', true);

    RETURN NULL;
END
$$;
